const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    var roi = ee.Geometry.Rectangle([-118.65, 33.90, -118.55, 34.05], null, false);
    var targetDate = '2015-10-10';
    var window1Start = '2015-10-08';
    var window1End = '2015-10-12';
    var window2Start = '2015-10-03';
    var window2End = '2015-10-17';

    // Helper: number->JS
    async function getNumber(x) { return x ? await x.getInfo() : null; }
    async function getString(x) { return x ? await x.getInfo() : null; }

    // 2. Sentinel-2 (primary)
    function maskS2clouds(img) {
      var qa = img.select('QA60');
      var cloud = qa.bitwiseAnd(1 << 10).eq(0);
      var cirrus = qa.bitwiseAnd(1 << 11).eq(0);
      return img.updateMask(cloud.and(cirrus));
    }
    function s2NDCI(img) {
      var b5 = img.select('B5'); // 705 nm
      var b4 = img.select('B4'); // 665 nm
      var ndci = b5.subtract(b4).divide(b5.add(b4).add(1e-6)).rename('ndci');
      return ndci.copyProperties(img, ['system:time_start']);
    }
    async function analyzeS2(start, end) {
      var col = ee.ImageCollection('COPERNICUS/S2')
        .filterBounds(roi)
        .filterDate(start, end)
        .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 80))
        .sort('CLOUDY_PIXEL_PERCENTAGE');
      var n = await col.size().getInfo();
      console.log(`S2 Images (${start}..${end}): ${n}`);
      if (!n || n === 0) return { ok: false, reason: 'C1' };
      var img0 = ee.Image(col.first());
      var img = maskS2clouds(img0);
      var date = await img.date().format('YYYY-MM-dd').getInfo();
      var totalCount = await getNumber(img0.select('B4').reduceRegion({
        reducer: ee.Reducer.count(), geometry: roi, scale: 1000, maxPixels: 1e9
      }).get('B4'));
      var validCount = await getNumber(img.select('B4').reduceRegion({
        reducer: ee.Reducer.count(), geometry: roi, scale: 1000, maxPixels: 1e9
      }).get('B4'));
      if (!totalCount || totalCount === 0) return { ok: false, reason: 'C2' };
      if (!validCount || validCount === 0) {
        console.log('S2 valid pixels after masking: 0');
        return { ok: false, reason: 'C2' };
      }
      var cloudScene = await getNumber(img0.get('CLOUDY_PIXEL_PERCENTAGE'));
      var ndci = s2NDCI(img);
      var ndciMean = await getNumber(ndci.reduceRegion({
        reducer: ee.Reducer.mean(), geometry: roi, scale: 1000, maxPixels: 1e9
      }).get('ndci'));
      var ndciThr = ndci.gt(0.05).selfMask();
      var thrCount = await getNumber(ndciThr.reduceRegion({
        reducer: ee.Reducer.count(), geometry: roi, scale: 1000, maxPixels: 1e9
      }).get('ndci'));
      var frac = thrCount && validCount ? (thrCount / validCount) : 0;
      var roiCloudPct = (1 - (validCount / totalCount)) * 100.0;

      console.log(`S2 Chosen Date: ${date}, Scene Cloud%: ${cloudScene !== null ? cloudScene.toFixed(1) : 'NA'}, ROI Cloud%: ${roiCloudPct.toFixed(1)}`);
      console.log(`S2 Pixels: valid ${validCount}/${totalCount}, NDCI mean: ${ndciMean !== null ? ndciMean.toFixed(4) : 'null'}, >0.05 frac: ${(frac * 100).toFixed(1)}%`);

      if (ndciMean === null || !isFinite(ndciMean)) return { ok: false, reason: 'C3' };
      var bloom = (frac >= 0.15) || (ndciMean >= 0.03);
      return { ok: true, bloom: bloom };
    }

    // 3. Landsat 8 fallback
    function maskL8(img) {
      var qa = img.select('QA_PIXEL');
      var mask = qa.bitwiseAnd(1 << 1).eq(0) // dilated cloud
        .and(qa.bitwiseAnd(1 << 2).eq(0))    // cirrus
        .and(qa.bitwiseAnd(1 << 3).eq(0))    // cloud
        .and(qa.bitwiseAnd(1 << 4).eq(0))    // cloud shadow
        .and(qa.bitwiseAnd(1 << 5).eq(0));   // snow
      // Scale reflectance
      var sr = img.select(['SR_B2','SR_B3','SR_B4','SR_B5','SR_B6']).multiply(0.0000275).add(-0.2);
      return sr.updateMask(mask).copyProperties(img, ['system:time_start']);
    }
    function l8FAI(sr) {
      var red = sr.select('SR_B4');
      var nir = sr.select('SR_B5');
      var swir = sr.select('SR_B6');
      var lambda_red = 0.655, lambda_nir = 0.865, lambda_swir = 1.61;
      var redToSwirSlope = swir.subtract(red).divide(lambda_swir - lambda_red);
      var redAtNir = red.add(redToSwirSlope.multiply(lambda_nir - lambda_red));
      return nir.subtract(redAtNir).rename('fai');
    }
    async function analyzeL8(start, end) {
      var col = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
        .filterBounds(roi)
        .filterDate(start, end)
        .filter(ee.Filter.lt('CLOUD_COVER', 80))
        .sort('CLOUD_COVER');
      var n = await col.size().getInfo();
      console.log(`L8 Images (${start}..${end}): ${n}`);
      if (!n || n === 0) return { ok: false, reason: 'C1' };
      var img0 = ee.Image(col.first());
      var img = maskL8(img0);
      var date = await img.date().format('YYYY-MM-dd').getInfo();
      var totalCount = await getNumber(img0.select('SR_B4').reduceRegion({
        reducer: ee.Reducer.count(), geometry: roi, scale: 1000, maxPixels: 1e9
      }).get('SR_B4'));
      var validCount = await getNumber(img.select('SR_B4').reduceRegion({
        reducer: ee.Reducer.count(), geometry: roi, scale: 1000, maxPixels: 1e9
      }).get('SR_B4'));
      if (!totalCount || totalCount === 0) return { ok: false, reason: 'C2' };
      if (!validCount || validCount === 0) {
        console.log('L8 valid pixels after masking: 0');
        return { ok: false, reason: 'C2' };
      }
      var fai = l8FAI(img);
      var faiMean = await getNumber(fai.reduceRegion({
        reducer: ee.Reducer.mean(), geometry: roi, scale: 1000, maxPixels: 1e9
      }).get('fai'));
      var faiThr = fai.gt(0.01).selfMask();
      var thrCount = await getNumber(faiThr.reduceRegion({
        reducer: ee.Reducer.count(), geometry: roi, scale: 1000, maxPixels: 1e9
      }).get('fai'));
      var frac = thrCount && validCount ? (thrCount / validCount) : 0;
      var roiCloudPct = (1 - (validCount / totalCount)) * 100.0;
      var cloudScene = await getNumber(img0.get('CLOUD_COVER'));

      console.log(`L8 Chosen Date: ${date}, Scene Cloud%: ${cloudScene !== null ? cloudScene.toFixed(1) : 'NA'}, ROI Cloud%: ${roiCloudPct.toFixed(1)}`);
      console.log(`L8 Pixels: valid ${validCount}/${totalCount}, FAI mean: ${faiMean !== null ? faiMean.toFixed(4) : 'null'}, >0.01 frac: ${(frac * 100).toFixed(1)}%`);

      if (faiMean === null || !isFinite(faiMean)) return { ok: false, reason: 'C3' };
      var bloom = (frac >= 0.10) || (faiMean >= 0.005);
      return { ok: true, bloom: bloom };
    }

    // Try S2 small window
    var res = await analyzeS2(window1Start, window1End);
    if (!res.ok && res.reason === 'C1') {
      // Try S2 expanded window
      res = await analyzeS2(window2Start, window2End);
    }
    if (!res.ok && res.reason === 'C1') {
      // Fallback to Landsat 8 small window
      res = await analyzeL8(window1Start, window1End);
      if (!res.ok && res.reason === 'C1') {
        // Fallback Landsat expanded
        res = await analyzeL8(window2Start, window2End);
      }
    }

    if (!res.ok) {
      console.log(res.reason);
      return;
    }

    // 5. Final decision from result
    console.log(res.bloom ? 'A: Yes' : 'B: No');
  } catch (e) {
    console.log('Error:', e.toString().slice(0, 200));
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
